// Every stop on the route loads, renders and animates, and scrolling its story sets what the stage shows, on each emulated
// device.
import { test, expect } from "@playwright/test";
import tour, { teaser } from "../../stops/tour.js";
import { watchErrors, stepsOf, shown } from "./helpers.mjs";

const cars = await Promise.all(tour.map(async s => (await import(`../../stops/${s.slug}/car.js`)).default));

for (const car of cars) {
  test(`${car.slug}: the story's steps set the stage, readouts move`, async ({ page }) => {
    const errors = watchErrors(page);
    await page.goto(`stop.html?s=${car.slug}&debug`);
    await page.waitForFunction(() => window.__tour?.stories[0].frames() > 10, null, { timeout: 20_000 });
    await expect(page.locator(".step")).toHaveCount(car.components.length + 2);

    const pinned = new Set();
    for (const [k, want] of stepsOf(car).entries()) {
      const step = page.locator(".step").nth(k);
      await step.evaluate(s => s.scrollIntoView({ block: "center" }));
      await expect.poll(() => shown(page)).toEqual({ step: k, state: want });
      await expect(page.locator(".stage img")).toBeVisible({ visible: want.view === "photo" });
      if (k === 0 || k > car.components.length) continue;   // intro and background: no component cards
      pinned.add(await page.locator(".stage").evaluate(s => Math.round(s.getBoundingClientRect().top)));
      await expect.poll(() => page.evaluate(() => window.__tour.stories[0].triangles())).toBeGreaterThan(0);
      const readouts = () => step.locator(`.panel[data-comp="${want.comp}"] output`).allTextContents();
      const before = await readouts();
      expect(before.length).toBeGreaterThan(0);
      await expect.poll(readouts, { timeout: 15_000 }).not.toEqual(before);
    }
    expect(pinned.size, "stage stays put through the component steps").toBe(1);

    const fit = await page.evaluate(() => ({ scrollW: document.documentElement.scrollWidth, w: innerWidth, h: innerHeight, stage: document.querySelector(".stage").getBoundingClientRect().height }));
    expect(fit.scrollW, "no horizontal scroll").toBeLessThanOrEqual(fit.w);
    expect(fit.stage, "stage fits the viewport height").toBeLessThanOrEqual(fit.h);
    expect(errors).toEqual([]);
  });
}

test("index lists every stop in walking order", async ({ page }) => {
  const errors = watchErrors(page);
  await page.goto("./");
  const links = page.locator('a[href^="stop.html?s="]');
  await expect(links).toHaveCount(tour.length);
  expect(await links.evaluateAll(as => as.map(a => new URL(a.href).searchParams.get("s")))).toEqual(tour.map(s => s.slug));
  expect(errors).toEqual([]);
});

test("unknown stop shows the not-found message and loads no 3D code", async ({ page }) => {
  const three = [];
  page.on("request", r => { if (/vendor\/three|subsystems\//.test(r.url())) three.push(r.url()); });
  await page.goto("stop.html?s=../../etc");
  await expect(page.getByRole("heading", { name: "Stop not found" })).toBeVisible();
  expect(three).toEqual([]);
});

test("teaser lists its three stops; opened from there, they page between each other", async ({ page }) => {
  const errors = watchErrors(page);
  const order = tour.filter(s => teaser.includes(s.slug)).map(s => s.slug), href = s => `stop.html?s=${s}&r=teaser`;
  await page.goto("teaser.html?debug");
  await page.waitForLoadState("networkidle");   // leaving mid-load aborts imports
  const links = page.locator('a[href^="stop.html?s="]');
  await expect(links).toHaveCount(3);
  expect(await links.evaluateAll(as => as.map(a => a.getAttribute("href")))).toEqual(order.map(href));

  for (const [i, slug] of order.entries()) {
    await page.goto(`${href(slug)}&debug`);
    await page.waitForFunction(() => window.__tour?.stories[0].frames() > 5, null, { timeout: 20_000 });   // leaving mid-load aborts imports
    await expect(page.locator("#where")).toContainText(`Stop ${i + 1} of 3`);
    await expect(page.getByRole("link", { name: "← Highlights" })).toHaveAttribute("href", "teaser.html");
    const pager = await page.locator(".pager a").evaluateAll(as => as.map(a => a.getAttribute("href")));
    expect(pager).toEqual([order[i - 1], order[i + 1]].filter(Boolean).map(href));
  }

  const other = tour.find(s => !teaser.includes(s.slug)).slug;   // not a teaser stop: the full tour's paging
  await page.goto(`stop.html?s=${other}&r=teaser&debug`);
  await page.waitForFunction(() => window.__tour?.stories[0].frames() > 5, null, { timeout: 20_000 });
  await expect(page.locator("#where")).toContainText(`of ${tour.length}`);
  await expect(page.getByRole("link", { name: "← Tour route" })).toHaveAttribute("href", "./");
  expect(errors).toEqual([]);
});

test("teaser: each car's stage stays pinned while its steps scroll past and set what it shows", async ({ page }) => {
  const errors = watchErrors(page);
  await page.goto("teaser.html?debug");
  await page.waitForFunction(() => window.__tour?.ready, null, { timeout: 30_000 });
  const frames = () => page.evaluate(() => window.__tour.stories.map(s => s.frames()));

  for (const [i, car] of cars.filter(c => teaser.includes(c.slug)).entries()) {
    const el = page.locator(".story").nth(i), steps = stepsOf(car);
    await expect(el.locator(".step")).toHaveCount(steps.length);
    const pinned = new Set();
    for (const [k, want] of steps.entries()) {
      await el.locator(".step").nth(k).evaluate(s => s.scrollIntoView({ block: "center" }));
      await expect.poll(() => shown(page, i)).toEqual({ step: k, state: want });
      if (want.view !== "model") continue;
      pinned.add(await el.locator(".stage").evaluate(s => Math.round(s.getBoundingClientRect().top)));
      if (k > 1) continue;   // on the first component: only this car's stage animates
      await page.waitForTimeout(300);
      const f0 = await frames(); await page.waitForTimeout(600); const f1 = await frames();
      expect(f1.map((f, j) => f > f0[j]), "animating stages").toEqual(f1.map((_, j) => j === i));
    }
    expect(pinned.size, "stage stays put through the component steps").toBe(1);
  }

  const fit = await page.evaluate(() => ({ scrollW: document.documentElement.scrollWidth, w: innerWidth, h: innerHeight, stage: document.querySelector(".story .stage").getBoundingClientRect().height }));
  expect(fit.scrollW, "no horizontal scroll").toBeLessThanOrEqual(fit.w);
  expect(fit.stage, "stage fits the viewport height").toBeLessThanOrEqual(fit.h);
  expect(errors).toEqual([]);
});
// Shared by the e2e specs.
export function watchErrors(page) {
  const errors = [];
  page.on("pageerror", e => errors.push(`pageerror: ${e.message}`));
  page.on("console", m => { if (m.type() === "error") errors.push(`console: ${m.text()}`); });
  return errors;
}

// What each step of a car's story (lib/app/story.js) puts on the stage: intro on the photo, one step per component in 3D,
// background on the photo with the car outline. A car without a photo shows its model instead (lib/app/viewer.js).
export const stepsOf = car => {
  const first = car.components[0].id, photo = car.photo ? "photo" : "model";
  return [{ comp: first, view: photo, outline: false }, ...car.components.map(c => ({ comp: c.id, view: "model", outline: false })), { comp: first, view: photo, outline: true }];
};

// The page's ?debug handle for story i: the step at the reading line and what the stage shows.
export const shown = (page, i = 0) => page.evaluate(i => ({ step: window.__tour.stories[i].step(), state: window.__tour.stories[i].state() }), i);
// Tubular space frame under a twisting load: one front wheel is lifted, the rear is held, as when a car crosses a kerb at
// an angle. Tubes are coloured by force (tension, compression) and the bending is drawn hugely exaggerated. Compare the
// 300 SL frame, whose side trusses run deep through the door area (so the doors had to open upwards), with the same frame
// cut down to a low sill for ordinary doors.
// Params (mm, ground at z = 0): label, stations, bays (lib/model/truss.js; door: "high" marks the door bays), EA (N),
// load (N at the front-left corner), exaggerate (× displacement), modes { high, low } (button labels), compare? (label
// of the stiffness-ratio readout: "high" is the reference).
import * as THREE from "three";
import { V, rod, place, ball } from "../lib/scene/helpers.js";
import { tubeFrame, twistTest } from "../lib/model/truss.js";

export function create(ctx, p) {
  const { stage, carRoot, t } = ctx;
  const group = new THREE.Group(); carRoot.add(group);
  const tens = stage.tokenMat("--l1"), comp = stage.tokenMat("--l4"), idle = stage.tokenMat("--metal");
  const solve = door => {
    const f = tubeFrame(p.stations, p.bays.map(b => (b.door ? { ...b, door } : b)), p.EA), r = twistTest(f, 0, p.stations.length - 1, p.load);
    const maxF = Math.max(...r.forces.map(Math.abs)), base = f.nodes.map(n => V(n[0] / 1000, n[1] / 1000, n[2] / 1000));
    const tubes = f.members.map((mb, i) => {
      const F = r.forces[i], t = rod(Math.abs(F) < 0.06 * maxF ? idle : F > 0 ? tens : comp, mb.tag.startsWith("door") ? 0.009 : 0.007);
      group.add(t); return { t, ends: mb.ends };
    });
    return { ...r, f, maxF, base, tubes };
  };
  const modes = { high: solve("high"), low: solve("low") };

  // Load arrow at the lifted corner, small balls where the frame is held.
  const nodeOf = (s, side, lv) => s * 6 + side * 3 + lv, last = p.stations.length - 1;
  const lift = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.16, 16), stage.tokenMat("--l2")); lift.rotation.x = Math.PI / 2; group.add(lift);
  const liftRod = rod(stage.tokenMat("--l2"), 0.015); group.add(liftRod);
  const supports = [nodeOf(last, 0, 0), nodeOf(last, 1, 0), nodeOf(0, 1, 0)].map(n => { const b = ball(stage.tokenMat("--muted"), 0.035); group.add(b); return { b, n }; });

  let mode = "high", clock = 0, playing = !ctx.reducedMotion, f = 0.5;
  const ui = ctx.panel([{ label: p.label, items: [
    { buttons: [{ id: "high", label: p.modes.high, pressed: true, onClick: () => setMode("high") }, { id: "low", label: p.modes.low, pressed: false, onClick: () => setMode("low") }] },
    { readouts: [{ id: "load", label: t("Lift at the front wheel"), unit: t("N") }, { id: "twist", label: t("Frame twist"), unit: t("deg") },
      { id: "stiff", label: t("Twist stiffness"), unit: t("N·m per degree") }, { id: "rel", label: p.compare ?? t("Compared with the 300 SL frame"), unit: "%" },
      { id: "maxF", label: t("Hardest-working tube"), unit: t("N") }] },
    { buttons: [{ id: "play", toggle: [t("Pause"), t("Play")], pressed: playing, onClick: v => (playing = v) }] },
    { key: [["--l1", t("tube in tension")], ["--l4", t("in compression")], ["--metal", t("hardly loaded")], ["--l2", t("lift")], ["--muted", t("held")]] },
    { text: t("Bending drawn {0}× larger than it is. Tube sizes and frame shape are simplified.", p.exaggerate) },
  ] }]);
  function setMode(md) { mode = md; ui.toggle("high").set(md === "high"); ui.toggle("low").set(md === "low"); }

  const q = V(0, 0, 0), a = V(0, 0, 0), b = V(0, 0, 0);
  const posOf = (s, n, out) => out.copy(s.base[n]).addScaledVector(q.set(...s.u[n]).multiplyScalar(1 / 1000), p.exaggerate * f);
  return {
    layout({ active }) { group.visible = active; },
    update(dt) {
      if (playing) { clock += dt; f = 0.5 - 0.5 * Math.cos(clock * 1.4); }
      for (const [k, s] of Object.entries(modes)) for (const tb of s.tubes) {
        tb.t.visible = k === mode;
        if (k === mode) place(tb.t, posOf(s, tb.ends[0], a), posOf(s, tb.ends[1], b).clone());
      }
      const s = modes[mode], corner = posOf(s, nodeOf(0, 0, 0), a);
      lift.position.copy(corner).add(q.set(0, 0, -0.12)); place(liftRod, corner.clone().add(q.set(0, 0, -0.42)), corner.clone().add(q.set(0, 0, -0.14)));
      for (const sp of supports) posOf(s, sp.n, sp.b.position).add(q.set(0, 0, -0.04));
      ui.set("load", (p.load * f).toFixed(0)); ui.set("twist", (s.twist * f).toFixed(3));
      ui.set("stiff", s.stiffness.toFixed(0)); ui.set("rel", (s.stiffness / modes.high.stiffness * 100).toFixed(0));
      ui.set("maxF", (s.maxF * f).toFixed(0));
    },
  };
}

/* Layout shared by the index and every stop, after the current mercedes-benz.com pages: black header bar and hero, white
   page, condensed serif headlines, black photo cards with 12 px corners, pill buttons. Light by default, dark on request.
   Colours are tokens and the 3-D scene reads them too; --band and --card are the fixed-black areas. */
/* Instrument Serif (SIL OFL 1.1, fonts/OFL.txt), standing in for the brand's proprietary condensed serif. Two subsets, as
   Google Fonts splits it: latin-ext carries Hungarian ő and ű and loads only on pages that use them. */
@font-face {
  font-family: "Instrument Serif"; font-weight: 400; font-style: normal; font-display: swap;
  src: url("fonts/instrument-serif-latin-400.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F,
    U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Instrument Serif"; font-weight: 400; font-style: normal; font-display: swap;
  src: url("fonts/instrument-serif-latin-ext-400.woff2") format("woff2");
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF,
    U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;
}
:root {
  --bg: #ffffff; --panel: #f4f4f4; --fg: #333333; --muted: #696969; --rule: #e8e8e8; --edge: #9f9f9f;
  --accent: #0078d6; --stage: #ececec;
  --band: #000000; --band-fg: #ffffff; --band-muted: #bbbbbb; --band-edge: #696969; --card: #000000;
  --l1: #d9480f; --l2: #e8a317; --l3: #2b8a3e; --l4: #1c64c4; --l5: #8e44ad;
  --metal: #8a96a1; --warn: #c92a2a;
  --cfd-1: #2b3fa0; --cfd-2: #2c9be0; --cfd-3: #5fd068; --cfd-4: #f2c230; --cfd-5: #d8341e;   /* wind-tunnel colour field, both themes */
  --display: "Instrument Serif", ui-serif, Georgia, "Times New Roman", serif;
  --body: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --gutter: clamp(16px, 4vw, 40px); --max: 1320px; --radius: 12px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #000000; --panel: #161616; --fg: #ffffff; --muted: #a3a3a3; --rule: #333333; --edge: #696969;
    --stage: #111111; --card: #161616;
    --l1: #ff7a45; --l2: #f5c242; --l3: #5cc46f; --l4: #5b9bf0; --l5: #b77fd6; --metal: #6f7c87; --warn: #ff6b6b;
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #000000; --panel: #161616; --fg: #ffffff; --muted: #a3a3a3; --rule: #333333; --edge: #696969;
  --stage: #111111; --card: #161616;
  --l1: #ff7a45; --l2: #f5c242; --l3: #5cc46f; --l4: #5b9bf0; --l5: #b77fd6; --metal: #6f7c87; --warn: #ff6b6b;
  color-scheme: dark;
}
[hidden] { display: none !important; }
