/* Black header bar: the page's own link on the left, where-am-I on the right. Static in index.html and stop.html. */
.bar { background: var(--band); color: var(--band-muted); padding: env(safe-area-inset-top) max(var(--gutter), env(safe-area-inset-right)) 0 max(var(--gutter), env(safe-area-inset-left)); }
.crumbs { max-width: calc(var(--max) - 2 * var(--gutter)); margin: 0 auto; min-height: 64px; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 0 16px; font-size: 14px; }
.crumbs a, .crumbs .home { display: inline-flex; align-items: center; min-height: 44px; color: var(--band-fg); text-decoration: none; }
.crumbs .home { font-family: var(--display); font-size: 24px; letter-spacing: 0; }
.crumbs a:hover { text-decoration: underline; }
