.langs button[aria-pressed="true"] { background: var(--band-fg); border-color: var(--band-fg); color: var(--band); }
.translating [data-i18n] { visibility: hidden; }   /* lang.js sets it; i18n.js removes it once the text is translated */
.pager { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px 24px; border-top: 1px solid var(--rule); padding-top: 16px; }
.pager a { display: inline-flex; align-items: center; min-height: 44px; font-family: var(--display); font-size: 24px; letter-spacing: 0; text-decoration: none; }
.pager a:hover { text-decoration: underline; }

/* Pill buttons: 44 px targets, no double-tap zoom. Selected = filled, like the site's brand switcher. */
button, .pill { display: inline-flex; align-items: center; justify-content: center; font: 700 14px/1.2 var(--body); letter-spacing: .2px; color: var(--fg); background: transparent; border: 1px solid var(--edge); border-radius: 9999px; padding: 10px 20px; min-height: 44px; cursor: pointer; touch-action: manipulation; text-decoration: none; }
button[aria-pressed="true"] { background: var(--fg); border-color: var(--fg); color: var(--bg); }
.pill.primary { background: var(--accent); border-color: var(--accent); color: var(--band-fg); }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.label { font-size: 13px; color: var(--muted); }

/* Stage (viewer.js): keeps the museum photo's aspect so the overlay lines up; the story layout below sizes it to leave room
   for scrolling past the touch-locked stage. */
.stage {
  --ar: 1.4944; position: relative; background: var(--stage); border-radius: var(--radius);
  aspect-ratio: var(--aspect, 1200 / 803); width: min(100%, calc((100svh - 32px) * var(--ar))); justify-self: center;
  overflow: hidden; touch-action: none; -webkit-user-select: none; user-select: none;
}
