.stage .credit { position: absolute; right: 10px; bottom: 8px; font-size: 10px; color: #f1f3f5; background: rgba(0,0,0,.55); padding: 2px 8px; border-radius: 9999px; }
.stage .credit a { color: inherit; }
.stage .fail { position: absolute; inset: 0; margin: 0; padding: 16px; }
.panel { background: var(--panel); border-radius: var(--radius); padding: 20px; display: grid; gap: 12px; min-width: 0; }
.readouts { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px 8px; }
.readouts div { display: grid; gap: 1px; }
.readouts output { font: 300 24px/1.2 var(--body); font-variant-numeric: tabular-nums; }
.readouts small { font-size: 12px; color: var(--muted); }
.row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.slider { display: grid; gap: 4px; }
input[type=range] { width: 100%; min-height: 32px; accent-color: var(--accent); }
.trace svg, svg.diagram { width: 100%; height: auto; display: block; }
.trace text, svg.diagram text { font-family: var(--mono); font-size: 9px; fill: var(--muted); }
.key { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px; color: var(--muted); }
.key i { display: inline-block; width: 14px; height: 3px; vertical-align: middle; margin-right: 5px; }
.legend { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-size: 14px; }
.legend li { display: grid; grid-template-columns: 12px 1fr; gap: 10px; align-items: center; }
.legend .sw { width: 12px; height: 12px; border-radius: 3px; }
.cyls { display: grid; grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr)); gap: 6px; }
.cyl { border: 1px solid var(--rule); border-radius: 8px; padding: 6px 2px; display: grid; gap: 2px; text-align: center; min-width: 0; background: var(--bg); }
