.cyl.power { border-color: var(--l1); box-shadow: inset 0 -3px 0 var(--l1); }
.badge { display: inline-block; font-size: 12px; padding: 1px 10px; border: 1px solid var(--edge); border-radius: 9999px; color: var(--muted); }
