/* Index route: one section per room, black photo cards whose picture fades into the card under the title. */
.route { list-style: none; margin: 0; padding: 0; display: grid; gap: 72px; }
.room-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 16px; margin-bottom: 28px; }
