.cyl { border: 1px solid var(--rule); border-radius: 8px; padding: 6px 2px; display: grid; gap: 2px; text-align: center; min-width: 0; background: var(--bg); }
.cyl b { font-family: var(--mono); font-size: 11px; color: var(--muted); font-weight: 500; }
